package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd(int, int).
 * Designed to maximize branch and line coverage.
 */
public class MathUtils_gcd_TriageGen1Test {

    @Test
    public void testGcdBasic() {
        // Standard positive integers
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(1, MathUtils.gcd(7, 13));
        assertEquals(5, MathUtils.gcd(10, 5));
        assertEquals(5, MathUtils.gcd(5, 10));
    }

    @Test
    public void testGcdWithNegatives() {
        // The implementation makes u and v negative, so sign should not affect result
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
        assertEquals(6, MathUtils.gcd(-12, -18));
    }

    @Test
    public void testGcdWithZero() {
        // Case: (u == 0) || (v == 0)
        // returns Math.abs(u) + Math.abs(v)
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(10, MathUtils.gcd(-10, 0));
        assertEquals(10, MathUtils.gcd(0, -10));
    }

    @Test(expected = RuntimeException.class)
    public void testGcdWithIntegerMinValueAndZero() {
        // Case: (u == Integer.MIN_VALUE) || (v == Integer.MIN_VALUE) within the zero check
        // This triggers the MathRuntimeException (wrapped in RuntimeException if not caught)
        MathUtils.gcd(Integer.MIN_VALUE, 0);
    }

    @Test(expected = RuntimeException.class)
    public void testGcdWithZeroAndIntegerMinValue() {
        MathUtils.gcd(0, Integer.MIN_VALUE);
    }

    @Test
    public void testGcdPowersOfTwo() {
        // Test B1: Find power of 2 logic
        // gcd(16, 32) -> k=5, u=1, v=1 -> returns 1 * 2^5 = 32 (Wait, gcd(16,32) is 16)
        // Let's trace: u=-16, v=-32. k=0.
        // loop: u=-8, v=-16, k=1; u=-4, v=-8, k=2; u=-2, v=-4, k=3; u=-1, v=-2, k=4.
        // loop ends because u is odd. k=4.
        // u=-1, v=-2. t = (u is odd) ? v : -(u/2) => t = -2.
        // t is even, t /= 2 => t = -1.
        // t is negative, v = -1.
        // t = (v-u)/2 = (-1 - (-1))/2 = 0.
        // returns -(-1) * (1 << 4) = 16. Correct.
        assertEquals(16, MathUtils.gcd(16, 32));
        assertEquals(8, MathUtils.gcd(8, 24));
    }

    @Test
    public void testGcdLargeOddAndEven() {
        // B2/B3/B4/B5/B6 logic
        // Test u odd, v even
        assertEquals(1, MathUtils.gcd(3, 4));
        // Test u even, v odd
        assertEquals(1, MathUtils.gcd(4, 3));
    }

    @Test
    public void testGcdMinValues() {
        // Integer.MIN_VALUE is -2^31.
        // Since it's negative, the code handles it via the "make u negative" logic
        // but it's already negative.
        // gcd(Integer.MIN_VALUE, 1) -> u=-2^31, v=-1.
        // k=0. u is even, v is odd.
        // t = -(u/2) = -(-2^30) = 2^30.
        // t is positive, u = -2^30.
        // loop continues...
        // This tests the boundary of integer limits.
        assertEquals(1, MathUtils.gcd(Integer.MIN_VALUE, 1));
        assertEquals(1, MathUtils.gcd(1, Integer.MIN_VALUE));
    }

    @Test
    public void testGcdComplex() {
        // Test a more complex sequence to ensure the do-while loop runs multiple times
        // gcd(48, 18)
        // u=-48, v=-18. k=1. u=-24, v=-9.
        // u is even, v is odd. t = -(u/2) = 12.
        // t is even, t=6, t=3.
        // t is positive, u=-3.
        // t = (v-u)/2 = (-9 - (-3))/2 = -3.
        // t is negative, v=-3.
        // t = (v-u)/2 = (-3 - (-3))/2 = 0.
        // returns -(-3) * 2^1 = 6.
        assertEquals(6, MathUtils.gcd(48, 18));
    }
}
